// DefaultRefPatterns are the patterns Entire's server authorizes its RSL
// signer for.
var DefaultRefPatterns = []string{"git:refs/heads/*", "git:refs/tags/*", "git:refs/entire/checkpoints/*"}

// NewRepo creates an empty repository with no gittuf policy.
func NewRepo(t *testing.T) *Repo {
	t.Helper()

	dir := t.TempDir()
	return &Repo{
		t:       t,
		Dir:     dir,
		Git:     gitinterface.CreateTestGitRepository(t, dir, false),
		Root:    NewKey(t, "root"),
		Cluster: NewKey(t, "cluster"),
		Rogue:   NewKey(t, "rogue"),
	}
}

// NewBenchRepo creates an empty repository for benchmarks. Unlike NewRepo it
// uses the real clock, so its object IDs differ between runs.
func NewBenchRepo(b testing.TB) *Repo {
	b.Helper()

	dir := b.TempDir()
	for _, args := range [][]string{
		{"init", "--quiet", "-b", "main", dir},
		{"-C", dir, "config", "user.name", committerName},
		{"-C", dir, "config", "user.email", committerEmail},
	} {
		if out, err := exec.CommandContext(b.Context(), "git", args...).CombinedOutput(); err != nil {
			b.Fatalf("git %v: %v: %s", args, err, out)
		}
	}

	repo, err := gitinterface.LoadRepository(dir)
	if err != nil {
		b.Fatalf("load repository: %v", err)
	}
	return &Repo{
		t:       b,
		Dir:     dir,
		Git:     repo,
		Root:    NewKey(b, "root"),
		Cluster: NewKey(b, "cluster"),
		Rogue:   NewKey(b, "rogue"),
	}
}

// Bootstrap applies a root of trust signed by Root that authorizes Cluster to
// sign RSL entries for patterns, the way Entire's server roots a repository.
func (r *Repo) Bootstrap(patterns ...string) {
	r.t.Helper()

	if len(patterns) == 0 {
		patterns = DefaultRefPatterns
	}

	_, err := policy.Bootstrap(context.Background(), r.Git, policy.BootstrapParams{
		RootSigners:         []crypto.Signer{r.Root.Private},
		RootPublicKeys:      []crypto.PublicKey{r.Root.Public},
		RootThreshold:       1,
		RSLSignerPublicKeys: []crypto.PublicKey{r.Cluster.Public},
		RefPatterns:         patterns,
		Expires:             time.Date(2100, time.January, 1, 0, 0, 0, 0, time.UTC),
	})
	if err != nil {
		r.t.Fatalf("bootstrap gittuf policy: %v", err)
	}
}

// Clone clones r from its LocalURL into a new directory with git, under
// remote name. git clone fetches branches and tags only, so the clone has no
// gittuf refs.
func (r *Repo) Clone(t *testing.T, remote string) string {
	t.Helper()

	dir := t.TempDir()
	cmd := exec.CommandContext(t.Context(), "git", "clone", "--quiet", "--origin", remote, "--", LocalURL(r.Dir), dir)
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("clone %s: %v: %s", r.Dir, err, out)
	}
	return dir
}

// AddWorktree adds a linked worktree of r, detached at rev, and returns its
// directory.
func (r *Repo) AddWorktree(t *testing.T, rev string) string {
	t.Helper()

	dir := filepath.Join(t.TempDir(), "worktree")
	cmd := exec.CommandContext(t.Context(), "git", "-C", r.Dir, "worktree", "add", "--quiet", "--detach", "--", dir, rev)
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("add worktree: %v: %s", err, out)
	}
	return dir
}

// AddRemote adds a remote to the repository at dir.
func AddRemote(t *testing.T, dir, name, url string) {
	t.Helper()

	cmd := exec.CommandContext(t.Context(), "git", "-C", dir, "remote", "add", "--", name, url)
	if out, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("add remote %s: %v: %s", name, err, out)
	}
}

